const extendMode = `
	// MIT License
	// Copyright © 2023 Zaron
	// Permission is hereby granted, free of charge, to any person obtaining a copy of this software and associated documentation files (the "Software"), to deal in the Software without restriction, including without limitation the rights to use, copy, modify, merge, publish, distribute, sublicense, and/or sell copies of the Software, and to permit persons to whom the Software is furnished to do so, subject to the following conditions:
	// The above copyright notice and this permission notice shall be included in all copies or substantial portions of the Software.
	// THE SOFTWARE IS PROVIDED "AS IS", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR IMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY, FITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE AUTHORS OR COPYRIGHT HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER LIABILITY, WHETHER IN AN ACTION OF CONTRACT, TORT OR OTHERWISE, ARISING FROM, OUT OF OR IN CONNECTION WITH THE SOFTWARE OR THE USE OR OTHER DEALINGS IN THE SOFTWARE.

	// Image extend mode - hold
	vec4 hold(vec2 uv, sampler2D img) {
		return texture2D(img, uv);
	}

	// Image extend mode - mirror
	vec4 mirror(vec2 uv, sampler2D img) {
		vec2 iuv = floor(uv);
		uv *= 1.-2.*mod(iuv, 2.);
		return texture2D(img, fract(uv));
	}

	// Image extend mode - one
	vec4 one(vec2 uv, sampler2D img) {
		if (0. <= uv.x && uv.x <= 1. && 0. <= uv.y && uv.y <= 1.) {
			return texture2D(img, uv);
		}
		else { return vec4(1.); }
	}

	// Image extend mode - repeat
	vec4 repeat(vec2 uv, sampler2D img) {
		return texture2D(img, fract(uv));
	}

	// Image extend mode - zero
	vec4 zero(vec2 uv, sampler2D img) {
		if (0. <= uv.x && uv.x <= 1. && 0. <= uv.y && uv.y <= 1.) {
			return texture2D(img, uv);
		}
		else { return vec4(0.); }
	}

	// Coordinate extend mode - mirror
	vec2 mirror(vec2 uv, float num) {
		uv *= num;
		vec2 iuv = floor(uv);
		uv *= 1.-2.*mod(iuv, 2.);
		return fract(uv);
	}

	// Coordinate extend mode - repeat
	vec2 repeat(vec2 uv, float num) {
		return fract(uv*num);
	}

	// Coordinate extend mode - repeat
	vec2 repeat(vec2 uv, vec2 num) {
		return fract(uv*num);
	}
`

// === Tab: frag ===
// noprotect

const frag = `
	#ifdef GL_ES
	precision mediump float;
	#endif

	uniform vec2 iResolution;
	uniform float iPixelDensity;
	uniform sampler2D iCanvas;
	uniform sampler2D iImage;
	uniform vec2 iMouse;
	uniform float iTime;
	uniform vec2 iGrid;

	${ snoise3D }
	${ snoise3DImage }
	${ displace }
	${ extendMode }

	float smoo3(float x) { return x*x*(3.-2.*x); }

	varying vec2 vTexCoord;
	void main() {
		vec2 uv = vTexCoord;
		vec2 mouse = iMouse.xy/iResolution.xy;
		uv.y = 1.-uv.y;

		// tiles
    vec2 tuv = repeat(uv, iGrid);
		tuv = abs(tuv-0.5);
		tuv = vec2(max(tuv.x, tuv.y));
		vec4 tiles = vec4(smoo3(smoo3(smoo3( tuv.x ))));

		// duv, make displace uv for Canvas
		float wei = sin(iTime*0.01)*0.02;
		vec2 duv = displace(uv, tiles.rg, 0., wei);
		duv = mirror(duv, 1.);

		// generate noise image
    float scal = min(iGrid.x, iGrid.y);
    float gain = 1.;
    float ofst = .5;
    float expo = 1.;
    vec3  move = vec3(0, 0, iTime*0.005);
    vec4 noise = snoise3DImage(uv, scal, gain, ofst, expo, move);

		// displace duv by noise image
		duv = displace(duv, noise.rg, ofst, .01);
		duv = mirror(duv, 1.);

		// tiles shadow
		float shadow = (1.-tiles.x);

		gl_FragColor = texture2D(iCanvas, duv)*shadow;
	}
`

// === Tab: vert ===
// Basic structure ref: https://itp-xstory.github.io/p5js-shaders/#/./docs/how-to-write-a-shader

const vert = `
	#ifdef GL_ES
	precision mediump float;
	#endif

	attribute vec3 aPosition;
	attribute vec2 aTexCoord;

	varying vec2 vTexCoord;

	void main() {
		vTexCoord = aTexCoord;
		vec4 positionVec4 = vec4(aPosition, 1.0);
		positionVec4.xy = positionVec4.xy * 2.0 - 1.0;
		gl_Position = positionVec4;
	}
`

